<div class="card border-0 shadow-sm mb-4"><div class="card-body d-flex justify-content-between align-items-center"><div><div class="small text-secondary"><?= html_escape($access['user']->email); ?></div><h2 class="h5 fw-bold mb-0"><?= html_escape(trim($access['user']->first_name . ' ' . $access['user']->last_name)); ?></h2><div class="small text-secondary">Username: <?= html_escape($access['user']->username); ?></div></div><a class="btn btn-outline-secondary" href="<?= site_url('admin/users'); ?>">Back to users</a></div></div>
