<?php if ((int) $access['user']->id === $current_user_id): ?><div class="alert alert-warning">For account safety, administrators cannot change their own role or permissions here.</div><?php endif; ?>
<form method="post" action="<?= site_url('admin/users/' . (int) $access['user']->id . '/access/save'); ?>">
    <input type="hidden" name="<?= html_escape($this->security->get_csrf_token_name()); ?>" value="<?= html_escape($this->security->get_csrf_hash()); ?>">
    <section class="card border-0 shadow-sm mb-4">
        <div class="card-header bg-white"><h3 class="h6 fw-bold mb-0">Role</h3></div>
        <div class="card-body"><label for="assignedRole" class="form-label">Assign role</label><select class="form-select" name="role_id" id="assignedRole" required <?= (int) $access['user']->id === $current_user_id ? 'disabled' : ''; ?>><?php foreach ($roles as $role): ?><option value="<?= (int) $role->id; ?>" <?= (int) $role->id === (int) $access['user']->role_id ? 'selected' : ''; ?> <?= !$role->is_active && (int) $role->id !== (int) $access['user']->role_id ? 'disabled' : ''; ?>><?= html_escape($role->role_name); ?><?= !$role->is_active ? ' (inactive)' : ''; ?></option><?php endforeach; ?></select><div class="form-text">Role permissions are inherited unless you set a user-specific override below.</div><?php if ((int) $access['user']->id === $current_user_id): ?><input type="hidden" name="role_id" value="<?= (int) $access['user']->role_id; ?>"><?php endif; ?></div>
    </section>
    <section class="card border-0 shadow-sm">
        <div class="card-header bg-white"><h3 class="h6 fw-bold mb-1">Individual access</h3><div class="small text-secondary">Allow adds access, Deny removes access inherited from the role, and Inherit follows the role.</div></div>
        <div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th class="ps-3">Permission</th><th>Role access</th><th>Effective access</th><th style="width: 190px">User override</th></tr></thead><tbody>
        <?php foreach ($access['permissions'] as $permission): ?><tr><td class="ps-3"><div class="fw-semibold"><?= html_escape($permission->name); ?></div><div class="small text-secondary"><?= html_escape($permission->module); ?> · <?= html_escape($permission->description); ?></div></td><td><?= $permission->role_granted ? 'Granted' : 'Not granted'; ?></td><td><span class="badge text-bg-<?= $permission->effective ? 'success' : 'secondary'; ?>"><?= $permission->effective ? 'Allowed' : 'Denied'; ?></span></td><td><select class="form-select form-select-sm" name="permission[<?= (int) $permission->id; ?>]" <?= (int) $access['user']->id === $current_user_id ? 'disabled' : ''; ?>><option value="inherit" <?= $permission->override_effect === 'inherit' ? 'selected' : ''; ?>>Inherit</option><option value="allow" <?= $permission->override_effect === 'allow' ? 'selected' : ''; ?>>Allow</option><option value="deny" <?= $permission->override_effect === 'deny' ? 'selected' : ''; ?>>Deny</option></select></td></tr><?php endforeach; ?>
        </tbody></table></div>
        <div class="card-body border-top"><label for="accessReason" class="form-label">Reason for access change <span class="text-secondary">(optional)</span></label><input class="form-control" id="accessReason" name="reason" maxlength="255" placeholder="Example: temporary finance coverage" <?= (int) $access['user']->id === $current_user_id ? 'disabled' : ''; ?>></div>
        <div class="card-footer bg-white d-flex justify-content-end gap-2"><a class="btn btn-outline-secondary" href="<?= site_url('admin/users'); ?>">Cancel</a><button class="btn btn-primary" type="submit" <?= (int) $access['user']->id === $current_user_id ? 'disabled' : ''; ?>>Save access</button></div>
    </section>
</form>
